import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.LX5S0jbT.js";const h=JSON.parse('{"title":"模型配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/models-configuration.md","filePath":"zh/models-configuration.md"}'),a={name:"zh/models-configuration.md"};function c(s,t,n,i,u,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="模型配置" tabindex="-1">模型配置 <a class="header-anchor" href="#模型配置" aria-label="Permalink to &quot;模型配置&quot;">​</a></h1><p>本参考列出 <code>models.json</code> 的字段。示例参见<a href="./models.html#configure-a-compatible-endpoint">配置兼容端点</a>，文件位置参见<a href="./configuration.html#agent-directory">配置</a>。</p><p>在 <code>models.json</code> 中添加 <code>&quot;$schema&quot;: &quot;https://pi.dev/schemas/models.schema.json&quot;</code> 以获得编辑器校验和补全。</p><h2 id="providers" tabindex="-1">提供商 <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;提供商 {#providers}&quot;">​</a></h2><p><code>providers</code> 下的每个键都是一个提供商（provider）ID。内置提供商 ID 会修改该提供商。其他 ID 则添加一个提供商，需要 <code>baseUrl</code> 以及提供商级或模型级的 <code>api</code>。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td></td><td>显示名称。</td></tr><tr><td><code>baseUrl</code></td><td>string</td><td></td><td>API 基础 URL。也适用于该提供商的内置模型。</td></tr><tr><td><code>apiKey</code></td><td>string</td><td></td><td>字面量密钥、&quot;$NAME&quot; 环境变量插值，或 &quot;!command&quot; 命令输出。</td></tr><tr><td><code>api</code></td><td>string</td><td></td><td>该提供商模型使用的 API，例如 &quot;openai-completions&quot;、&quot;openai-responses&quot;、&quot;anthropic-messages&quot; 或 &quot;google-generative-ai&quot;。</td></tr><tr><td><code>oauth</code></td><td><code>&quot;radius&quot;</code></td><td></td><td>OAuth 登录流程。需要 baseUrl。</td></tr><tr><td><code>headers</code></td><td>object</td><td></td><td>请求头。值的解析方式与 apiKey 相同。</td></tr><tr><td><code>compat</code></td><td><a href="#compatibility">object</a></td><td></td><td>提供商和模型兼容性覆盖。</td></tr><tr><td><code>authHeader</code></td><td>boolean</td><td><code>false</code></td><td>是否将解析后的 API 密钥作为 Authorization: Bearer 发送。</td></tr><tr><td><code>models</code></td><td><a href="#models"><code>object[]</code></a></td><td></td><td></td></tr><tr><td><code>modelOverrides</code></td><td><a href="#model-overrides">object</a></td><td></td><td></td></tr></tbody></table><h2 id="models" tabindex="-1">模型 <a class="header-anchor" href="#models" aria-label="Permalink to &quot;模型 {#models}&quot;">​</a></h2><p>每个 <code>models</code> 条目向提供商添加一个模型。<code>id</code> 与现有模型匹配的条目会替换它。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td></td><td>必填。发送到 API 的模型 ID。</td></tr><tr><td><code>name</code></td><td>string</td><td></td><td>显示名称，也参与 --model 模式匹配。</td></tr><tr><td><code>api</code></td><td>string</td><td></td><td>覆盖提供商 api。</td></tr><tr><td><code>baseUrl</code></td><td>string</td><td></td><td>覆盖提供商 baseUrl。</td></tr><tr><td><code>reasoning</code></td><td>boolean</td><td><code>false</code></td><td>模型是否支持思考（thinking）。</td></tr><tr><td><code>thinkingLevelMap</code></td><td>object</td><td></td><td>每个思考级别发送的提供商值。null 表示该级别不受支持。模型未映射的级别使用提供商默认值直至 high；xhigh 和 max 不受支持。</td></tr><tr><td><code>input</code></td><td><code>(&quot;text&quot; | &quot;image&quot;)[]</code></td><td><code>[&quot;text&quot;]</code></td><td></td></tr><tr><td><code>inputLimits</code></td><td><a href="#input-limits">object</a></td><td></td><td></td></tr><tr><td><code>cost</code></td><td>object</td><td></td><td></td></tr><tr><td><code>cost.input</code></td><td>number</td><td></td><td>必填。输入成本，美元/百万 token。</td></tr><tr><td><code>cost.output</code></td><td>number</td><td></td><td>必填。输出成本，美元/百万 token。</td></tr><tr><td><code>cost.cacheRead</code></td><td>number</td><td></td><td>必填。缓存读取成本，美元/百万 token。</td></tr><tr><td><code>cost.cacheWrite</code></td><td>number</td><td></td><td>必填。缓存写入成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers</code></td><td><code>object[]</code></td><td></td><td>按请求整体计价的定价档。最高的匹配输入阈值适用于整个请求。</td></tr><tr><td><code>cost.tiers[].inputTokensAbove</code></td><td>number</td><td></td><td>必填。当请求总输入超过此 token 数时使用该档。</td></tr><tr><td><code>cost.tiers[].input</code></td><td>number</td><td></td><td>必填。输入成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers[].output</code></td><td>number</td><td></td><td>必填。输出成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers[].cacheRead</code></td><td>number</td><td></td><td>必填。缓存读取成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers[].cacheWrite</code></td><td>number</td><td></td><td>必填。缓存写入成本，美元/百万 token。</td></tr><tr><td><code>promptCache</code></td><td>object</td><td></td><td>短保留档和长保留档的提示词缓存（prompt cache）有效期（秒），尽力估计。Pi 只预热已知有效期的档。</td></tr><tr><td><code>contextWindow</code></td><td>number</td><td><code>128000</code></td><td>上下文窗口，单位 token。</td></tr><tr><td><code>maxTokens</code></td><td>number</td><td><code>16384</code></td><td>最大输出 token 数。</td></tr><tr><td><code>samplingParams</code></td><td>object</td><td></td><td>合并进每个请求体的字段。仅适用于 OpenAI 兼容 API。</td></tr><tr><td><code>samplingParamsByThinkingLevel</code></td><td>object</td><td></td><td>每个思考级别的 samplingParams，合并到 samplingParams 之上。</td></tr><tr><td><code>headers</code></td><td>object</td><td></td><td>请求头。值的解析方式与 apiKey 相同。</td></tr><tr><td><code>compat</code></td><td><a href="#compatibility">object</a></td><td></td><td>提供商和模型兼容性覆盖。</td></tr></tbody></table><h2 id="model-overrides" tabindex="-1">模型覆盖 <a class="header-anchor" href="#model-overrides" aria-label="Permalink to &quot;模型覆盖 {#model-overrides}&quot;">​</a></h2><p>每个 <code>modelOverrides</code> 键是内置或扩展模型的 ID。未知 ID 被忽略。对象字段（如 <code>cost</code>）与模型现有值逐字段合并；其他字段直接替换。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td></td><td>显示名称，也参与 --model 模式匹配。</td></tr><tr><td><code>reasoning</code></td><td>boolean</td><td></td><td>模型是否支持思考。</td></tr><tr><td><code>thinkingLevelMap</code></td><td>object</td><td></td><td>每个思考级别发送的提供商值。null 表示该级别不受支持。模型未映射的级别使用提供商默认值直至 high；xhigh 和 max 不受支持。</td></tr><tr><td><code>input</code></td><td><code>(&quot;text&quot; | &quot;image&quot;)[]</code></td><td></td><td></td></tr><tr><td><code>inputLimits</code></td><td><a href="#input-limits">object</a></td><td></td><td></td></tr><tr><td><code>cost</code></td><td>object</td><td></td><td></td></tr><tr><td><code>cost.input</code></td><td>number</td><td></td><td>输入成本，美元/百万 token。</td></tr><tr><td><code>cost.output</code></td><td>number</td><td></td><td>输出成本，美元/百万 token。</td></tr><tr><td><code>cost.cacheRead</code></td><td>number</td><td></td><td>缓存读取成本，美元/百万 token。</td></tr><tr><td><code>cost.cacheWrite</code></td><td>number</td><td></td><td>缓存写入成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers</code></td><td><code>object[]</code></td><td></td><td>按请求整体计价的定价档。最高的匹配输入阈值适用于整个请求。</td></tr><tr><td><code>cost.tiers[].inputTokensAbove</code></td><td>number</td><td></td><td>必填。当请求总输入超过此 token 数时使用该档。</td></tr><tr><td><code>cost.tiers[].input</code></td><td>number</td><td></td><td>必填。输入成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers[].output</code></td><td>number</td><td></td><td>必填。输出成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers[].cacheRead</code></td><td>number</td><td></td><td>必填。缓存读取成本，美元/百万 token。</td></tr><tr><td><code>cost.tiers[].cacheWrite</code></td><td>number</td><td></td><td>必填。缓存写入成本，美元/百万 token。</td></tr><tr><td><code>promptCache</code></td><td>object</td><td></td><td>短保留档和长保留档的提示词缓存有效期（秒），尽力估计。Pi 只预热已知有效期的档。</td></tr><tr><td><code>contextWindow</code></td><td>number</td><td></td><td>上下文窗口，单位 token。</td></tr><tr><td><code>maxTokens</code></td><td>number</td><td></td><td>最大输出 token 数。</td></tr><tr><td><code>samplingParams</code></td><td>object</td><td></td><td>合并进每个请求体的字段。仅适用于 OpenAI 兼容 API。</td></tr><tr><td><code>samplingParamsByThinkingLevel</code></td><td>object</td><td></td><td>每个思考级别的 samplingParams，合并到 samplingParams 之上。</td></tr><tr><td><code>headers</code></td><td>object</td><td></td><td>请求头。值的解析方式与 apiKey 相同。</td></tr><tr><td><code>compat</code></td><td><a href="#compatibility">object</a></td><td></td><td>提供商和模型兼容性覆盖。</td></tr></tbody></table><h2 id="input-limits" tabindex="-1">输入限制 <a class="header-anchor" href="#input-limits" aria-label="Permalink to &quot;输入限制 {#input-limits}&quot;">​</a></h2><p>参见<a href="./models.html#describe-model-input-and-caching">描述模型输入与缓存</a>。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>maxRequestBytes</code></td><td>integer</td><td></td><td>序列化后提供商请求的最大字节数。</td></tr><tr><td><code>images</code></td><td>object</td><td></td><td></td></tr><tr><td><code>images.resize</code></td><td>object</td><td></td><td>在新图像进入对话历史之前应用的、缓存安全的缩放配置。</td></tr><tr><td><code>images.resize.maxWidth</code></td><td>integer</td><td></td><td></td></tr><tr><td><code>images.resize.maxHeight</code></td><td>integer</td><td></td><td></td></tr><tr><td><code>images.resize.maxBytes</code></td><td>integer</td><td></td><td>base64 编码后载荷的最大字节数。</td></tr><tr><td><code>images.resize.jpegQuality</code></td><td>integer</td><td></td><td></td></tr><tr><td><code>images.maxPerMessage</code></td><td>integer</td><td></td><td>单个提供商消息允许的最大图像数。</td></tr><tr><td><code>images.maxPerRequest</code></td><td>integer</td><td></td><td>单个提供商请求允许的最大图像数。</td></tr></tbody></table><h2 id="compatibility" tabindex="-1">兼容性 <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;兼容性 {#compatibility}&quot;">​</a></h2><p><code>compat</code> 描述与 API 标准请求和响应行为之间已验证的差异。模型值按字段覆盖提供商值。适用哪些字段取决于模型的 <code>api</code>。</p><h3 id="openai-completions" tabindex="-1"><code>openai-completions</code> <a class="header-anchor" href="#openai-completions" aria-label="Permalink to &quot;`openai-completions`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>supportsStore</code></td><td>boolean</td><td></td><td>提供商是否支持 store 字段。默认：从 URL 自动检测。</td></tr><tr><td><code>supportsDeveloperRole</code></td><td>boolean</td><td></td><td>提供商是否支持 developer 角色而不是 system。默认：从 URL 自动检测。</td></tr><tr><td><code>supportsReasoningEffort</code></td><td>boolean</td><td></td><td>提供商是否支持 reasoning_effort。默认：从 URL 自动检测。</td></tr><tr><td><code>supportsUsageInStreaming</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否支持 stream_options.include_usage，以便在流式响应中返回 token 用量。</td></tr><tr><td><code>supportsFinishReason</code></td><td>boolean</td><td><code>true</code></td><td>流式响应是否包含 finish_reason。为 false 时，pi 在流结束时推断 stop 或 toolUse。</td></tr><tr><td><code>maxTokensField</code></td><td><code>&quot;max_completion_tokens&quot; | &quot;max_tokens&quot;</code></td><td></td><td>用于 max tokens 的字段。默认：从 URL 自动检测。</td></tr><tr><td><code>requiresToolResultName</code></td><td>boolean</td><td></td><td>工具结果是否需要 name 字段。默认：从 URL 自动检测。</td></tr><tr><td><code>requiresAssistantAfterToolResult</code></td><td>boolean</td><td></td><td>工具结果之后的消息是否要求中间有 assistant 消息。默认：从 URL 自动检测。</td></tr><tr><td><code>requiresThinkingAsText</code></td><td>boolean</td><td></td><td>思考块是否必须转换为带 &lt;thinking&gt; 分隔符的文本块。默认：从 URL 自动检测。</td></tr><tr><td><code>requiresReasoningContentOnAssistantMessages</code></td><td>boolean</td><td></td><td>启用 reasoning 时，所有回放的 assistant 消息是否必须包含空的 reasoning_content 字段。默认：从 URL 自动检测。</td></tr><tr><td><code>thinkingFormat</code></td><td><code>&quot;openai&quot; | &quot;openrouter&quot; | &quot;deepseek&quot; | &quot;together&quot; | &quot;baseten&quot; | &quot;zai&quot; | &quot;qwen&quot; | &quot;chat-template&quot; | &quot;qwen-chat-template&quot; | &quot;string-thinking&quot; | &quot;ant-ling&quot;</code></td><td></td><td>reasoning/thinking 参数的格式。省略时 Pi 从提供商 URL 自动检测格式。&quot;openai&quot; 使用 reasoning_effort，&quot;openrouter&quot; 使用 reasoning.effort，&quot;deepseek&quot; 使用 thinking.type（支持时另加 reasoning_effort），&quot;together&quot; 使用 reasoning.enabled（支持时另加 reasoning_effort），&quot;baseten&quot; 使用可配置的 chat_template_args（支持时另加 reasoning_effort），&quot;zai&quot; 使用 thinking.type，&quot;qwen&quot; 使用顶层的 enable_thinking，&quot;qwen-chat-template&quot; 使用 chat_template_kwargs.enable_thinking 和 preserve_thinking，&quot;chat-template&quot; 使用可配置的 chat_template_kwargs，&quot;string-thinking&quot; 使用顶层 thinking，&quot;ant-ling&quot; 仅在映射的 effort 非空时使用 reasoning.effort。</td></tr><tr><td><code>chatTemplateKwargs</code></td><td>object</td><td></td><td>thinkingFormat 为 &quot;chat-template&quot; 时作为 chat_template_kwargs 发送的 kwargs。用 $var 配合 &quot;thinking.enabled&quot;、&quot;thinking.effort&quot; 或 &quot;thinking.budget&quot; 表示由 pi 控制的值。</td></tr><tr><td><code>chatTemplateArgs</code></td><td>object</td><td></td><td>thinkingFormat 为 &quot;baseten&quot; 时作为 chat_template_args 发送的参数。用 $var 配合 &quot;thinking.enabled&quot;、&quot;thinking.effort&quot; 或 &quot;thinking.budget&quot; 表示由 pi 控制的值。</td></tr><tr><td><code>openRouterRouting</code></td><td>object</td><td></td><td>OpenRouter 提供商路由偏好。控制 OpenRouter 将请求路由到哪些上游提供商。作为 provider 字段发送到 OpenRouter API 请求体。参见 <a href="https://openrouter.ai/docs/guides/routing/provider-selection%E3%80%82" target="_blank" rel="noreferrer">https://openrouter.ai/docs/guides/routing/provider-selection。</a></td></tr><tr><td><code>vercelGatewayRouting</code></td><td>object</td><td></td><td>Vercel AI Gateway 路由偏好。控制网关将请求路由到哪些上游提供商。参见 <a href="https://vercel.com/docs/ai-gateway/models-and-providers/provider-options%E3%80%82" target="_blank" rel="noreferrer">https://vercel.com/docs/ai-gateway/models-and-providers/provider-options。</a></td></tr><tr><td><code>zaiToolStream</code></td><td>boolean</td><td><code>false</code></td><td>z.ai 是否支持顶层 tool_stream 用于流式工具调用增量。</td></tr><tr><td><code>thinkingTokenBudgetField</code></td><td><code>&quot;thinking_token_budget&quot; | &quot;thinking_budget&quot; | &quot;thinking_budget_tokens&quot;</code></td><td></td><td>用于限制 thinkingBudgets 推理 token 的顶层请求字段。这些端点上 reasoning 与答案共享 max_tokens。&quot;thinking_token_budget&quot; 是 vLLM，&quot;thinking_budget&quot; 是 Qwen、DashScope 或 SGLang，&quot;thinking_budget_tokens&quot; 是 llama.cpp。默认关闭，且不在生成的目录中设置。</td></tr><tr><td><code>supportsThinkingTokenBudget</code></td><td>boolean</td><td><code>false</code></td><td>thinkingTokenBudgetField: &quot;thinking_token_budget&quot;（vLLM）的别名。优先使用 thinkingTokenBudgetField。</td></tr><tr><td><code>supportsOpenAIGrammarTools</code></td><td>boolean</td><td><code>false</code></td><td>提供商是否支持带 Lark 或 regex 文法格式的 OpenAI 自定义工具。为 false 时，文法约束工具回退为普通函数工具。生成的目录为有能力的模型启用它。</td></tr><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>该模型是否在对话开始后接受 system 或 developer 消息。为 false 时，后续 system 消息并入开头的 system 消息。生成的目录为已验证的模型启用它。</td></tr><tr><td><code>supportsMidConvoToolAdditions</code></td><td>boolean</td><td><code>false</code></td><td>system 消息是否可以在对话中途引入额外工具。需要 supportsMidConvoSystemMessages。生成的目录为有能力的模型启用它。</td></tr><tr><td><code>supportsStrictMode</code></td><td>boolean</td><td><code>false</code></td><td>提供商是否支持工具定义中的 strict 字段。生成的有能力的模型显式启用它。</td></tr><tr><td><code>cacheControlFormat</code></td><td><code>&quot;anthropic&quot;</code></td><td></td><td>提示词缓存的 cache control 约定。Anthropic 将 cache_control 标记应用于系统提示词、最后一个工具定义，以及最后的 user、assistant 或 tool-result 文本内容。</td></tr><tr><td><code>sendSessionAffinityHeaders</code></td><td>boolean</td><td></td><td>是否发送来自 options.sessionId 的会话亲和（session affinity）数据。默认：OpenRouter 端点为 true，其他为 false。</td></tr><tr><td><code>sessionAffinityFormat</code></td><td><code>&quot;openai&quot; | &quot;openai-nosession&quot; | &quot;openrouter&quot;</code></td><td></td><td>会话亲和头格式。openai 发送 session_id、x-client-request-id 和 x-session-affinity；openai-nosession 发送 x-client-request-id 和 x-session-affinity；openrouter 发送 x-session-id。不影响 prompt_cache_key。默认：自动检测。</td></tr><tr><td><code>supportsLongCacheRetention</code></td><td>boolean</td><td></td><td>提供商是否支持长提示词缓存保留（prompt_cache_retention: &quot;24h&quot; 或 Anthropic 风格的 cache_control.ttl: &quot;1h&quot;，取决于格式）。默认：从提供商和 URL 自动检测。</td></tr><tr><td><code>vllmPriority</code></td><td>number</td><td></td><td>作为顶层 priority 请求字段发送的 vLLM 调度器优先级。值越小越早处理，服务器默认值为 0。仅在与 --scheduling-policy priority 一起使用时有意义。默认关闭，且不在生成的目录中设置。</td></tr></tbody></table><h3 id="openai-responses" tabindex="-1"><code>openai-responses</code> <a class="header-anchor" href="#openai-responses" aria-label="Permalink to &quot;`openai-responses`&quot;">​</a></h3><p>也适用于 <code>azure-openai-responses</code> 和 <code>openai-codex-responses</code>。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>supportsDeveloperRole</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否支持 developer 角色而不是 system。</td></tr><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>该模型是否在对话开始后接受 developer 或 system 消息。为 false 时，后续 system 消息并入开头的 system 消息。生成的目录为已验证的模型启用它。</td></tr><tr><td><code>sessionAffinityFormat</code></td><td><code>&quot;openai&quot; | &quot;openai-nosession&quot; | &quot;openrouter&quot;</code></td><td></td><td>会话亲和头格式。openai 发送 session_id 和 x-client-request-id；openai-nosession 发送 x-client-request-id；openrouter 发送 x-session-id。不影响 prompt_cache_key。默认：自动检测。</td></tr><tr><td><code>supportsLongCacheRetention</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否支持长提示词缓存保留。在 GPT-5.6+ 上使用 prompt_cache_options.ttl: &quot;30m&quot;，在较早的模型上使用 prompt_cache_retention: &quot;24h&quot;。</td></tr><tr><td><code>supportsStrictMode</code></td><td>boolean</td><td></td><td>提供商是否支持 strict JSON-schema 函数工具。默认值因 API 而异；生成的 OpenAI 模型显式启用它。</td></tr><tr><td><code>supportsOpenAIGrammarTools</code></td><td>boolean</td><td><code>false</code></td><td>是否发送带 Lark 或 regex 文法格式的 OpenAI 自定义工具。为 false 时，文法约束工具回退为普通函数工具。生成的目录为有能力的模型启用它。</td></tr><tr><td><code>supportsAdditionalTools</code></td><td>boolean</td><td><code>false</code></td><td>模型是否支持锚定在消息上的 additional_tools 输入项。</td></tr><tr><td><code>supportsToolSearch</code></td><td>boolean</td><td><code>false</code></td><td>模型是否支持客户端执行的、锚定在会话记录上的工具搜索。</td></tr><tr><td><code>supportsExplicitPromptCacheMode</code></td><td>boolean</td><td><code>false</code></td><td>模型是否接受 prompt_cache_options。较旧的 OpenAI 模型会拒绝该参数。</td></tr><tr><td><code>supportsMidConvoEffort</code></td><td>boolean</td><td><code>false</code></td><td>思考级别变更是否作为 configuration_update 输入项发送，而不是修改 reasoning.effort，使变更保留提示词缓存。仅由 openai-responses API 使用，在 openai 提供商上使用 Sign in with ChatGPT 时忽略。</td></tr><tr><td><code>supportsMaxOutputTokens</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否接受 max_output_tokens。某些 Codex 协议网关会拒绝它。</td></tr></tbody></table><h3 id="anthropic-messages" tabindex="-1"><code>anthropic-messages</code> <a class="header-anchor" href="#anthropic-messages" aria-label="Permalink to &quot;`anthropic-messages`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>supportsEagerToolInputStreaming</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否接受每工具的 eager_input_streaming。为 false 时，Anthropic 提供商省略 tools[].eager_input_streaming，并在启用工具的请求中发送旧的 fine-grained-tool-streaming-2025-05-14 beta 头。</td></tr><tr><td><code>supportsLongCacheRetention</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否通过 cache_control.ttl 支持 Anthropic 长缓存保留。</td></tr><tr><td><code>sendSessionAffinityHeaders</code></td><td>boolean</td><td></td><td>启用缓存时是否从 options.sessionId 发送 x-session-affinity。Fireworks 等使用会话亲和做提示词缓存路由的提供商需要它；发往同一副本的请求可最大化缓存命中。默认：OpenRouter 端点为 true，其他为 false。</td></tr><tr><td><code>sessionAffinityFormat</code></td><td><code>&quot;openrouter&quot;</code></td><td></td><td>会话亲和格式。openrouter 发送 x-session-id；未设置时发送 x-session-affinity。</td></tr><tr><td><code>supportsCacheControlOnTools</code></td><td>boolean</td><td><code>true</code></td><td>提供商是否支持工具定义上的 Anthropic 风格 cache_control 标记。为 false 时，工具参数中省略 cache_control。某些 Anthropic 兼容提供商（如 Fireworks）不支持工具上的该字段，可能拒绝或忽略它。</td></tr><tr><td><code>supportsTemperature</code></td><td>boolean</td><td><code>true</code></td><td>模型是否接受 Anthropic 的 temperature 请求字段。Claude Opus 4.7+ 拒绝非默认值。</td></tr><tr><td><code>forceAdaptiveThinking</code></td><td>boolean</td><td><code>false</code></td><td>是否强制自适应思考（thinking.type: adaptive 加 output_config.effort），而不看模型 ID。需要自适应思考的内置模型在生成的元数据中设置此项。自定义 Anthropic 兼容提供商可以为上游要求自适应格式的任何模型将其设为 true。对被覆盖的内置模型设为 false 可退出。</td></tr><tr><td><code>allowEmptySignature</code></td><td>boolean</td><td><code>false</code></td><td>是否回放空的思考签名，而不是把思考转换为文本。</td></tr><tr><td><code>supportsStrictTools</code></td><td>boolean</td><td><code>false</code></td><td>提供商是否支持 Anthropic strict 工具 schema。生成的 Anthropic 模型显式启用它。</td></tr><tr><td><code>supportsMidConvoEffort</code></td><td>boolean</td><td><code>false</code></td><td>该模型的传输层是否支持仅含 effort 的 system 消息和思考绑定控制。</td></tr><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>该模型是否接受对话内的 system 角色消息。为 false 时，后续 system 消息并入顶层系统提示词。</td></tr><tr><td><code>supportsMidConvoToolChanges</code></td><td>boolean</td><td><code>false</code></td><td>该模型是否接受对话中途的 tool_addition 和 tool_removal 块。需要 supportsMidConvoSystemMessages。</td></tr><tr><td><code>allowedFallbackModels</code></td><td><code>object[]</code></td><td></td><td>Anthropic 接受用于服务端拒绝回退的模型，附带返回的回退响应的本地定价元数据。缺失或为空时，调用方必须省略回退；对没有允许回退目标的模型，Anthropic 会拒绝该字段。</td></tr></tbody></table><h3 id="bedrock-converse-stream" tabindex="-1"><code>bedrock-converse-stream</code> <a class="header-anchor" href="#bedrock-converse-stream" aria-label="Permalink to &quot;`bedrock-converse-stream`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>supportsStrictMode</code></td><td>boolean</td><td><code>false</code></td><td>模型是否支持 Bedrock strict 工具 schema。</td></tr></tbody></table><h3 id="mistral-conversations" tabindex="-1"><code>mistral-conversations</code> <a class="header-anchor" href="#mistral-conversations" aria-label="Permalink to &quot;`mistral-conversations`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>该模型是否在对话开始后接受 system 消息。为 false 时，后续 system 消息并入开头的 system 消息。</td></tr></tbody></table><p><a id="typesafe-system-one"></a></p><h3 id="typesafe-system-one" tabindex="-1"><code>typesafe-system-one</code> <a class="header-anchor" href="#typesafe-system-one" aria-label="Permalink to &quot;`typesafe-system-one`&quot;">​</a></h3><p>也适用于 <code>cloudflare-workers-ai-system-one</code>。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>imageInput</code></td><td><code>&quot;assets&quot; | &quot;images&quot; | &quot;state-image-urls&quot;</code></td><td></td><td>服务获取分类器图像的方式。&quot;assets&quot; 发送 TypeSafe 的 assets 映射（PNG 和 JPEG）并从状态中引用图像，正如 TypeSafe 和 Workers AI 上的 Jev 所期望的。&quot;images&quot; 发送 Clef 的 data URL 图像列表 images（PNG、JPEG 和 WebP，最多四张），正如 Workers AI 上的 Clef 所期望的。&quot;state-image-urls&quot; 将 image_url 部分放在状态之前，正如 OpenRouter 所期望的；OpenRouter 会丢弃 assets 且不报错。从提供商、baseUrl 和模型 ID 自动检测。分类器模型从提供商级 compat 读取它；models 和 modelOverrides 条目仅适用于聊天模型。</td></tr><tr><td><code>sendImageOptInHeader</code></td><td>boolean</td><td></td><td>带图像的请求是否发送 TypeSafe-Danger-Zone-Images: true 头，TypeSafe 自己的 API 对其实验性图像输入要求此头。在 typesafe-system-one API 上默认为 true，除非模型被检测为 OpenRouter。</td></tr></tbody></table>',32)])])}const m=d(a,[["render",c]]);export{h as __pageData,m as default};
